import numpy as np

def predict_corridor(bel, move):
    bel = np.asarray(bel, dtype=float)
    n = len(bel)
    out = np.zeros(n)
    for i in range(n):
        for k, p in move.items():
            j = min(max(i + k, 0), n - 1)      # the walls stop the robot at the end cells
            out[j] += p * bel[i]
    return out
